import React from 'react';

function About({ lang }) {
  return (
    <div>
      <h1>Coffee Time</h1>

      <p>
        {lang === 'ru'
          ? 'Уютная кофейня в центре города.'
          : 'Cozy coffee shop in the city center.'}
      </p>

      <p>
        {lang === 'ru'
          ? 'Мы готовим кофе из натуральных зерен высокого качества.'
          : 'We make coffee from high-quality natural beans.'}
      </p>
    </div>
  );
}

export default About;
